/**
 * Equal-track grid for card fields, stat rows and form pairs (`design/components/grid.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/grid.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  claimSlot,
  classes,
  mergeParts,
  scope,
  spacingAttrs,
  type Defaults,
  type LayoutPatch,
  type SpaceStep,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type GridAlign = NonNullable<GridProps['align']>

export type GridColumns = NonNullable<GridProps['columns']>

export type GridElement = NonNullable<GridProps['as']>

export interface GridProps {
  align?: 'stretch' | 'start' | 'center' | 'end'
  as?: 'div' | 'section' | 'ul'
  children?: JSX.Element
  columns?: 1 | 2 | 3 | 4 | 6 | 12
  gap?: SpaceStep
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
}

/** Equal-track grid for card fields, stat rows and form pairs. */
export default function Grid(given: GridProps): JSX.Element {
  const props = mergeProps(
    { columns: 2, align: 'stretch', as: 'div' } as Defaults<GridProps, 'columns' | 'align' | 'as'>,
    claimSlot(given),
  )
  return scope(() => {
    return (
      <Dynamic
        component={props.as}
        {...mergeParts(
          spacingAttrs({
            gap: props.gap,
            p: props.p,
            px: props.px,
            py: props.py,
            patch: props.patch,
          }),
          {
            class: classes(styles.layout, styles.grid),
            'data-columns': String(props.columns),
            'data-align': props.align,
            'data-member': 'grid',
          },
        )}
      >
        {props.children}
      </Dynamic>
    )
  })
}
